__NUXT_JSONP__("/anticorrupcion/eventos/suman_esfuerzos_gobierno_organismos_autonomos_y_sociedad_civil_para_evaluar_tramites_en_6_municipios_de_quintana_roo", (function(a,b,c,d,e){return {data:[{post:{slug:"suman_esfuerzos_gobierno_organismos_autonomos_y_sociedad_civil_para_evaluar_tramites_en_6_municipios_de_quintana_roo",title:"Suman esfuerzos gobierno, organismos autónomos  y sociedad civil para evaluar trámites en 6 municipios de Quintana Roo",date:"2023-10-09T21:52:34.766Z",img:"https:\u002F\u002Fucarecdn.com\u002F73000610-bd1b-4b3a-b679-ee8880df5d95\u002F","img-alt":"Mejora regulatoria Ethos",autor:"Ethos",category:"anticorrupcion",extracto:"A través de una evaluación de la percepción de la ciudadanía y empresariado en trámites de licencia de conducir, uso de suelo y anuencia de protección civil, se detectarán áreas de oportunidad para mejorar estos servicios gubernamentales.",toc:[],body:{type:"root",children:[{type:b,tag:c,props:{},children:[{type:a,value:"La evaluación de los trámites y servicios públicos que los gobiernos brindan a la ciudadanía permite identificar áreas de oportunidad y trabajar en ellas. Es por ello que el Gobierno del Estado de Quintana Roo, el Sistema Estatal Anticorrupción,  el Comité de Participación Ciudadana y su Secretaría Ejecutiva, en coordinación con Ethos, diseñaron el proyecto «Impacto en la implementación de programas de mejora regulatoria en 6 municipios del estado de Quintana Roo»."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Al presentarlo a servidores públicos de la entidad, así como integrantes de cámaras empresariales, el investigador Héctor Tirado, del área de Finanzas Públicas y Anticorrupción en Ethos, explicó que consiste en la aplicación de encuestas focalizadas, a través de las cuales se obtendrá información sobre tres trámites específicos en 6 municipios quintanarroenses: Benito Juárez, Solidaridad, Othón P. Blanco, Tulum, Isla Mujeres y Felipe Carrillo Puerto."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Las encuestas serán sobre tres trámites: licencia de conducir, dirigida a la ciudadanía, así como uso de suelo y anuencia de protección civil, dirigidos a empresarias y empresarios del estado. “Queremos conocer los avances y resultados a través de la percepción de las personas usuarias de estos trámites y del empresariado”, señaló."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Asimismo, invitó a las y los asistentes a este evento virtual a apoyar en la difusión de este proyecto, ya que mientras más quintanarroenses participen en él, se contará con más datos para generar un análisis y afinar las áreas que se pueden mejorar."}]}]},dir:"\u002Feventos",path:"\u002Feventos\u002Fsuman_esfuerzos_gobierno_organismos_autonomos_y_sociedad_civil_para_evaluar_tramites_en_6_municipios_de_quintana_roo",extension:".md",createdAt:e,updatedAt:e}}],fetch:{},mutations:[]}}("text","element","p","\n","2023-10-11T01:03:45.049Z")));